REPLACE INTO `partidas` (`id`, `capitulo_id`, `subcapitulo`, `partida_generica`, `codigo`, `nombre`, `descripcion`, `activo`, `created_at`, `updated_at`, `deleted_at`) VALUES
	(1, 1, '1100', NULL, '11101', 'Dietas', 'Asignaciones para remuneraciones a los Diputados, Senadores, Asambleístas, Regidores y Síndicos.', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(2, 1, '1100', NULL, '11102', 'Emolumentos.- Asignaciones para remuneraciones a los delegados y subdelegados que nombra el H. Ayuntamiento.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(3, 1, '1100', NULL, '11301', 'Sueldos base al personal permanente.- Asignaciones para remuneraciones al personal civil, de base o de confianza, de carácter permanente que preste sus servicios en los entes públicos. Los montos que importen estas remuneraciones serán fijados de acuerdo con los catálogos institucionales de puestos de los entes públicos.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(4, 1, '1100', NULL, '11302', 'Salarios al personal de Confianza.- Asignaciones destinadas a cubrir las remuneraciones a personal de confianza, de las dependencias.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(5, 1, '1200', NULL, '12101', 'Honorarios asimilables a salarios.- Asignaciones destinadas a cubrir el pago por la prestación de servicios contratados con personas físicas, como profesionistas, técnicos, expertos y peritos, entre otros, por estudios, obras o trabajos determinados que correspondan a su especialidad. El pago de honorarios deberá sujetarse a las disposiciones aplicables. Esta partida excluye los servicios profesionales contratados con personas físicas o morales previstos en el Capítulo 3000 Servicios Generales.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(6, 1, '1200', NULL, '12102', 'Honorarios.- Asignaciones destinadas a cubrir el pago por la prestación de servicios personales contratados, bajo este régimen fiscal, para el desempeño de actividades propias de la administración municipal.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(7, 1, '1200', NULL, '12201', 'Sueldos base al personal eventual.- Asignaciones destinadas a cubrir las remuneraciones para el pago al personal de carácter transitorio que preste sus servicios en los entes públicos.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(8, 1, '1200', NULL, '12301', 'Retribuciones por servicios de carácter social.- Asignaciones destinadas a cubrir las remuneraciones a profesionistas de las diversas carreras o especialidades técnicas que presten su servicio social en los entes públicos.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(9, 1, '1300', NULL, '13101', 'Primas por años de servicios efectivos prestados.- Asignaciones adicionales como complemento al sueldo del personal al servicio de los entes públicos, por años de servicios efectivos prestados, de acuerdo con la legislación aplicable.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(10, 1, '1300', NULL, '13201', 'Primas de vacaciones.- Asignaciones al personal que tenga derecho a vacaciones o preste sus servicios en domingo.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(11, 1, '1300', NULL, '13202', 'Prima Dominical.- Asignaciones al personal que  preste sus servicios en domingo.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(12, 1, '1300', NULL, '13203', 'Gratificación fin de año.- Asignaciones al personal que tenga derecho a aguinaldo o gratificación de fin de año al personal civil y militar al servicio de los entes públicos.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(13, 1, '1300', NULL, '13301', 'Remuneraciones por horas extraordinarias al personal administrativo.- Asignaciones por remuneraciones a que tenga derecho el personal de los entes públicos por servicios prestados en horas que se realizan excediendo la duración máxima de la jornada de trabajo, guardias o turnos opcionales.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(14, 1, '1300', NULL, '13302', 'Remuneraciones por horas extraordinarias al personal operativo.- Asignaciones por remuneraciones a que tenga derecho el personal de los entes públicos por servicios prestados en horas que se realizan excediendo la duración máxima de la jornada de trabajo, guardias o turnos opcionales.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(15, 1, '1300', NULL, '13401', 'Compensaciones.- Asignaciones destinadas a cubrir las percepciones que se otorgan a los servidores públicos bajo el esquema de compensaciones que determinen las disposiciones aplicables.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(16, 1, '1300', NULL, '13402', 'Retribuciones por actividades especiales.- Asignaciones destinadas a cubrir al personal de las dependencias, el pago por servicios prestados fuera de la jornada normal de trabajo relacionados con su cargo o servicios especiales que desempeñen.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(17, 1, '1300', NULL, '13403', 'Compensaciones extraordinarias.- Asignaciones destinadas a cubrir al personal de las dependencias, el pago por programas especiales.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(18, 1, '1300', NULL, '13501', 'Sobrehaberes.- Remuneraciones adicionales que se cubre al personal militar en activo en atención al incremento en el costo de la vida o insalubridad del lugar donde preste sus servicios.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(19, 1, '1400', NULL, '14101', 'Aportaciones de seguridad social.- Asignaciones destinadas a cubrir la aportación de los entes públicos, por concepto de seguridad social, en los términos de la legislación vigente.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(20, 1, '1400', NULL, '14201', 'Aportaciones a fondos de vivienda.- Asignaciones destinadas a cubrir las aportaciones que corresponden a los entes públicos para proporcionar vivienda a su personal, de acuerdo con las disposiciones legales vigentes.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(21, 1, '1400', NULL, '14301', 'Aportaciones al sistema para el retiro.- Asignaciones destinadas a cubrir los montos de las aportaciones de los entes públicos a favor del Sistema para el Retiro, correspondientes a los trabajadores al servicio de los mismos.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(22, 1, '1400', NULL, '14401', 'Aportaciones para seguros.- Asignaciones destinadas a cubrir las primas que corresponden a los entes públicos por concepto de seguro de vida, seguro de gastos médicos del personal a su servicio; así como, los seguros de responsabilidad civil y asistencia legal, en los términos de la legislación vigente. Incluye las primas que corresponden al Gobierno Federal por concepto de seguro de vida del personal militar.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(23, 1, '1500', NULL, '15101', 'Cuotas para el fondo de ahorro.- Asignaciones destinadas a cubrir las cuotas que corresponden a los entes públicos para la constitución del fondo de ahorro del personal civil, según acuerdos contractuales establecidos. Incluye cuotas para la constitución del fondo de ahorro.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(24, 1, '1500', NULL, '15102', 'Cuotas para el fondo de ahorro para el retiro.- Asignaciones que se destinan para el pago del fondo de ahorro para el retiro para los funcionarios de elección popular, de acuerdo a lo dispuesto por la Ley para el Ejercicio y Control de los Recursos Públicos para el Estado y los Municipios de Guanajuato.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(25, 1, '1500', NULL, '15201', 'Indemnizaciones.- Asignaciones destinadas a cubrir indemnizaciones al personal conforme a la legislación aplicable; tales como: por accidente de trabajo, por despido, entre otros.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(26, 1, '1500', NULL, '15202', 'Liquidaciones por indemnizaciones y por sueldos y salarios caídos.- Asignaciones destinadas a cubrir el pago de indemnización por liquidación y el pago de salarios y sueldos caídos cuando se separa a un trabajador.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(27, 1, '1500', NULL, '15301', 'Prestaciones y haberes de retiro.- Erogaciones que los entes públicos realizan en beneficio de sus empleados por jubilaciones, haberes de retiro, pensiones, retiro voluntario entre otros, cuando estas prestaciones no sean cubiertas por las instituciones de seguridad social. Incluye las asignaciones por concepto de aguinaldo a favor de pensionistas, cuyo pago se realice con cargo al erario. Incluye compensaciones de retiro a favor del personal del Servicio Exterior Mexicano, en los términos de la ley de la materia.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(28, 1, '1500', NULL, '15401', 'Liquidación prima quinquenal.- Asignaciones destinadas al pago de las liquidaciones de las primas quinquenales, a los funcionarios y empleados al servicio de las dependencias.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(29, 1, '1500', NULL, '15402', 'Ayudas para gastos de defunción.- Asignaciones destinadas a cubrir el pago por  ayuda para gastos de defunción, a favor de los empleados de base y de confianza que laboran para las dependencias.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(30, 1, '1500', NULL, '15403', 'Ayuda de transporte.- Asignaciones que se destinan para cubrir el pago por concepto de ayuda de transporte a los empleados de base y de confianza, al servicio del municipio, de conformidad con los planes autorizados.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(31, 1, '1500', NULL, '15404', 'Ayuda para educación.- Asignaciones que las dependencias destinan para cubrir el pago por concepto de ayuda para educación del personal de base y de confianza, como parte de los planes de previsión social.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(32, 1, '1500', NULL, '15405', 'Ayuda para despensa.- Asignaciones que se destinan para cubrir el pago por concepto de ayuda para despensa al personal de base y de confianza, como parte de los planes de previsión social.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(33, 1, '1500', NULL, '15406', 'Becas para hijos de trabajadores.- Asignaciones destinadas a cubrir el pago de becas para hijos de trabajadores que las dependencias realizan en beneficio del personal a su servicio.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(34, 1, '1500', NULL, '15407', 'Ayuda para Día de Reyes.- Asignaciones destinadas a cubrir el pago de la ayuda para el día de reyes, que se realiza a los empleados de base y de confianza al servicio de las dependencias.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(35, 1, '1500', NULL, '15408', 'Ayuda para 10 de Mayo.- Asignaciones destinadas a cubrir el pago de la ayuda para el día 10 de mayo, que se realiza a los empleados de base y de confianza al servicio de las dependencias.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(36, 1, '1500', NULL, '15501', 'Apoyos a la capacitación de los servidores públicos.- Erogaciones destinadas a apoyar la capacitación orientada al desarrollo personal o profesional de los servidores públicos que determinen los entes públicos o que en forma individual se soliciten, de conformidad con las disposiciones que se emitan para su otorgamiento. Excluye las erogaciones por capacitación comprendidas en el capítulo 3000 Servicios Generales.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(37, 1, '1500', NULL, '15901', 'Apoyo Familiar.- Asignaciones destinadas a cubrir al personal de las dependencias, los importes preestablecidos que se otorgan como ayuda para mejorar el nivel adquisitivo familiar.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(38, 1, '1500', NULL, '15902', 'Premio por puntualidad.- Asignaciones destinadas a cubrir el pago que las dependencias realizan en beneficio del personal de base y de confianza, por concepto de premio por puntualidad.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(39, 1, '1500', NULL, '15903', 'Premio por asistencia.- Asignaciones destinadas a cubrir el pago que las dependencias realizan en beneficio del personal de base y de confianza, por concepto de premio por puntualidad.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(40, 1, '1500', NULL, '15904', 'Ayuda para alimentación.- Asignaciones destinadas a cubrir el pago que las dependencias realizan en beneficio del personal de base y de confianza, por concepto de ayuda para alimentación.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(41, 1, '1500', NULL, '15905', 'Subsidio por incapacidad.- Asignaciones que se destinan al pago de los subsidios por incapacidad, emitidos por el I.M.S.S., a favor de los empleados de base y de confianza, cuyos importes serán devueltos por el propio I.M.S.S., de conformidad con los convenios existentes entre el municipio y esta Institución.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(42, 1, '1500', NULL, '15906', 'Subsidio para impuesto.- Asignaciones destinadas a cubrir los pagos por concepto de subsidio por los impuestos causados, a cargo de los trabajadores, que el municipio otorga, con la finalidad de disminuir el impacto de las cargas fiscales que afectan a las percepciones reales de los trabajadores de base y de confianza.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(43, 1, '1500', NULL, '15907', 'Subsidio para Cuotas a cargo del Patrón', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(44, 1, '1500', NULL, '15908', 'Prestaciones Sindicales', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(45, 1, '1500', NULL, '15909', 'Otras prestaciones sociales y económica', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(46, 1, '1600', NULL, '16101', 'Previsiones de carácter laboral, económica y de seguridad social.- Asignaciones destinadas a cubrir las medidas de incremento en percepciones, creación de plazas, aportaciones en términos de seguridad social u otras medidas de carácter laboral o económico de los servidores públicos que se aprueben en el Presupuesto de Egresos. Esta partida no se ejercerá en forma directa, sino a través de las partidas que correspondan a los demás conceptos del capítulo 1000 Servicios Personales, que sean objeto de traspaso de estos recursos. Estas se considerarán como transitorias en tanto se distribuye su monto entre las partidas específicas necesarias para los programas, por lo que su asignación se afectará una vez ubicada en las partidas correspondientes, según la naturaleza de las erogaciones y previa aprobación, de acuerdo con lineamientos específicos.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(47, 1, '1700', NULL, '17101', 'Estímulos.- Asignaciones destinadas a cubrir los estímulos al personal de los entes públicos puntualidad y asistencia, entre otros; de acuerdo con la normatividad aplicable.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(48, 1, '1700', NULL, '17102', 'Estímulos a la productividad.-  Asignaciones que se destinan al pago de estímulos a los empleados de base y de confianza, derivados de la evaluación a su productividad, por el cumplimiento de metas.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(49, 1, '1700', NULL, '17103', 'Estímulos por antigüedad al personal.- Asignaciones que las dependencias destinan para cubrir el pago en beneficio del personal por el tiempo efectivo de servicios prestados para el municipio.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(50, 2, '2100', NULL, '21101', 'Materiales y útiles de oficina', 'Asignaciones destinadas a la adquisición de materiales, artículos diversos y equipos menores propios para el uso de las oficinas tales como: papelería, formas, libretas, carpetas y cualquier tipo de papel, útiles de escritorio como engrapadoras, perforadoras manuales, sacapuntas; artículos de dibujo, correspondencia y archivo; cestos de basura y otros productos similares entre otros. Podrán cargarse a esta partida los artículos que aparecen a continuación:', 1, '2026-03-03 18:50:17', '2026-04-29 16:04:03', NULL),
	(51, 2, '2100', NULL, '21201', 'Materiales y útiles de impresión y reproducción.- Asignaciones destinadas a la adquisición de materiales utilizados en la impresión, reproducción y encuadernación, tales como: fijadores, tintas, pastas, logotipos y demás materiales y útiles para el mismo fin. Incluye rollos fotográficos.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(52, 2, '2100', NULL, '21301', 'Material estadístico y geográfico.- Asignaciones destinadas a la adquisición de publicaciones relacionadas con información estadística y geográfica. Se incluye la cartografía y publicaciones tales como: las relativas a indicadores económicos y socio-demográficos, cuentas nacionales, estudios geográficos y geodésicos, mapas, planos, fotografías aéreas y publicaciones relacionadas con información estadística y geográfica.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(53, 2, '2100', NULL, '21401', 'Materiales y útiles de tecnologías de la información y comunicaciones', 'Asignaciones destinadas a la adquisición de insumos y equipos menores utilizados en el procesamiento, grabación e impresión de datos, así como los materiales para la limpieza y protección de los equipos tales como: tóner, medios ópticos y magnéticos, apuntadores y protectores, entre otros. Podrán cargarse a esta partida los artículos que aparecen a continuación', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(54, 2, '2100', NULL, '21501', 'Material impreso e información digital.- Asignaciones destinadas a la adquisición de toda clase de libros, revistas, periódicos, publicaciones, diarios oficiales, gacetas, material audiovisual, casetes, discos compactos distintos a la adquisición de bienes intangibles (software). Incluye la suscripción a revistas y publicaciones especializadas, folletos, catálogos, formatos y otros productos mediante cualquier técnica de impresión y sobre cualquier tipo de material. Incluye impresión sobre prendas de vestir, producción de formas continuas, impresión rápida, elaboración de placas, clichés y grabados. Excluye conceptos considerados en la partida 2131 Material estadístico y geográfico. Podrán cargarse a esta partida los artículos que aparecen a continuación:', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(55, 2, '2100', NULL, '21601', 'Material de limpieza', 'Asignaciones destinadas a la adquisición de materiales, artículos y enseres para el aseo, limpieza e higiene, tales como: escobas, jergas, detergentes, jabones y otros productos similares. Podrán cargarse a esta partida los artículos que aparecen a continuación', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(56, 2, '2100', NULL, '21701', 'Materiales y útiles de enseñanza.- Asignaciones destinadas a la adquisición de todo tipo de material didáctico así como materiales y suministros necesarios para las funciones educativas. Podrán cargarse a esta partida los artículos que aparecen a continuación:', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(57, 2, '2100', NULL, '21801', 'Materiales para el registro e identificación de bienes y personas.- Asignaciones destinadas a la adquisición de materiales requeridos para el registro e identificación en trámites oficiales y servicios a la población, tales como: pasaportes, certificados especiales, formas valoradas, placas de tránsito, licencias de conducir, entre otras.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(58, 2, '2200', NULL, '22101', 'Alimentos para el personal institucional', 'Asignaciones destinadas a la adquisición de todo tipo de productos alimenticios y bebidas manufacturados o no, independiente de la modalidad de compra o contratación, derivado trabajo por tiempo extra o en días inhábiles derivado de programas que requieren permanencia de servidores públicos en instalaciones del ente público, así como en el desempeño de actividades extraordinarias en el cumplimiento de la función pública. Excluye Viáticos (partidas 3751 y 3761), gastos derivados del concepto 3800 Servicios Oficiales y 1331 y 1332 Horas Extraordinarias no justificadas.', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(59, 2, '2200', NULL, '22102', 'Productos alimenticios para preparar alimentos.- Asignaciones destinadas a la adquisición de todo tipo de productos alimenticios y bebidas para la preparación de alimentos de personas, que por sus actividades, horarios y programación laborales, es necesario que el Municipio les provea la alimentación.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(60, 2, '2200', NULL, '22201', 'Productos alimenticios para animales.- Asignaciones destinadas a la adquisición de productos alimenticios para la manutención de animales propiedad o bajo el cuidado de los entes públicos, tales como: forrajes frescos y achicalados, alimentos preparados, entre otros, así como los demás gastos necesarios para la alimentación de los mismos. Podrán cargarse a esta partida los artículos que aparecen a continuación:', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(61, 2, '2200', NULL, '22301', 'Utensilios para el servicio de alimentación.- Asignaciones destinadas a la adquisición de todo tipo de utensilios necesarios para proporcionar este servicio, tales como: vajillas, cubiertos, baterías de cocina, licuadoras, tostadoras, cafeteras, básculas y demás electrodomésticos y bienes consumibles en operaciones a corto plazo.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(62, 2, '2300', NULL, '23101', 'Productos alimenticios, agropecuarios y forestales adquiridos como materia prima.- Asignaciones destinadas a la adquisición de productos alimenticios como materias primas en estado natural, transformadas o semi-transformadas, de naturaleza vegetal y animal que se utilizan en los procesos productivos, diferentes a las contenidas en las demás partidas de este Clasificador.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(63, 2, '2300', NULL, '23102', 'Productos de naturaleza vegetal y forestal adquiridos como materia prima.- Asignaciones destinadas a la adquisición de productos de naturaleza vegetal y forestal como materias primas en estado natural, transformadas o semi-transformadas, tales como plantas, entre otros, necesarias para las Dependencias diferentes a las contenidas en las demás partidas de este Clasificador. (Arboles, plantas, etc.)', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(64, 2, '2300', NULL, '23301', 'Productos de papel, cartón e impresos adquiridos como  productos de papel, cartón e impresos adquiridos como materia  prima.- Asignaciones destinadas a la adquisición de productos de papel, cartón e impresos adquiridos como  productos de papel, cartón e impresos adquiridos como materia  prima', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(65, 2, '2300', NULL, '23901', 'Otros productos, adquisición de materia prima.- Asignaciones destinadas a la adquisición de otros productos  como materias primas en estado natural, transformadas o semi-transformadas, necesarias para las Dependencias diferentes a las contenidas en las demás partidas de este Clasificador. Tierra, abono, macetas, bolsas de uso diferente al de la basura), etc.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(66, 2, '2400', NULL, '24101', 'Productos minerales no metálicos', 'Asignaciones destinadas a la adquisición de productos de para la construccion como arcillas refractarias y no refractarias y cerámica y otros similares para la construcción; loza y porcelana para diversos usos como inodoros, lavamanos, mingitorios y otros similares. Podrán cargarse a esta partida los artículos que aparecen a continuacion.', 1, '2026-03-03 18:50:17', '2026-03-03 20:01:59', NULL),
	(67, 2, '2400', NULL, '24201', 'Cemento y productos de concreto', 'Asignaciones destinadas a la adquisición de cemento blanco, gris y especial, pega azulejo y productos de concreto (láminas de asbesto).', 1, '2026-03-03 18:50:17', '2026-03-03 20:01:00', NULL),
	(68, 2, '2400', NULL, '24301', 'Cal, yeso y productos de yeso.- Asignaciones destinadas a la adquisición de tabla roca, plafones, paneles acústicos, columnas, molduras, estatuillas, figuras decorativas de yeso y otros productos arquitectónicos de yeso de carácter ornamental. Incluye dolomita calcinada. Cal viva, hidratada o apagada y cal para usos específicos a partir de piedra caliza triturada.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(69, 2, '2400', NULL, '24401', 'Madera y productos de madera.- Asignaciones destinadas a la adquisición de madera y sus derivados.', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(70, 2, '2400', NULL, '24501', 'Vidrio y productos de vidrio.- Asignaciones destinadas a la adquisición de vidrio plano, templado, inastillable y otros vidrios laminados; espejos; envases y artículos de vidrio y fibra de vidrio (láminas).', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(71, 2, '2400', NULL, '24601', 'Material eléctrico y electrónico', 'Asignaciones destinadas a la adquisición de todo tipo de material eléctrico y electrónico que requieran las líneas de transmisión telegráfica, telefónica y de telecomunicaciones, igualmente para la adquisición de materiales necesarios en las instalaciones radiofónicas, radiotelegráficas, entre otras. Podrán cargarse a esta partida los artículos que aparecen a continuación.', 1, '2026-03-03 18:50:17', '2026-03-03 19:59:58', NULL),
	(72, 2, '2400', NULL, '24701', 'Artículos metálicos para la construcción', 'Asignaciones destinadas a cubrir los gastos por adquisición de productos para construcción hechos de hierro, acero, aluminio, cobre, zinc, bronce y otras aleaciones, entre otros. Podrán cargarse a esta partida los artículos que aparecen a continuacion', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(73, 2, '2400', NULL, '24801', 'Materiales complementarios', 'Asignaciones destinadas a la adquisición de materiales para el acondicionamiento de los bienes inmuebles, así como materiales no contenidos en las partidas y conceptos anteriores y que por su naturaleza sea un gasto excepcional y demás accesorios, entre otros. Podrán cargarse a esta partida los artículos que aparecen a continuacion', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(74, 2, '2400', NULL, '24901', 'Otros materiales y artículos de construcción y reparación', 'Asignaciones destinadas a cubrir la adquisición de otros materiales para construcción y reparación no considerados en las partidas anteriores tales como: Productos de fricción o abrasivos a partir de polvos minerales sintéticos o naturales para obtener productos como piedras amolares, esmeriles de rueda, abrasivos en polvo, entre otros. Podrán cargarse a esta partida los artículos que aparecen a continuacion.', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(75, 2, '2500', NULL, '25101', 'Productos químicos básicos.- Asignaciones destinadas a la adquisición de productos químicos básicos y sustancias químicas, entre otros. Podrán cargarse a esta partida los artículos que aparecen a continuacion:', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(76, 2, '2500', NULL, '25201', 'Fertilizantes, pesticidas y otros agroquímicos.- Asignaciones destinadas a la adquisición de fertilizantes nitrogenados, fosfatados, biológicos procesados o de otro tipo, mezclas, fungicidas, herbicidas, plaguicidas, raticidas, antigerminantes, reguladores del crecimiento de las plantas y nutrientes de suelos, entre otros. Incluye los abonos que se comercializan en estado natural. Podrán cargarse a esta partida los artículos que aparecen a continuacion:', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
	(77, 2, '2500', NULL, '25301', 'Medicinas y productos farmacéuticos.- Asignaciones destinadas a la adquisición de medicinas y productos farmacéuticos de aplicación humana o animal. Incluye productos fármaco-químicos como alcaloides, antibióticos, hormonas y otros compuestos y principios activos entre otros. Podrán cargarse a esta partida los artículos que aparecen a continuacion:', 'Importado Masivamente', 1, '2026-03-03 18:50:17', '2026-03-03 18:50:17', NULL),
